20: ImagingPcxDecode(Imaging im, ImagingCodecState state, UINT8* buf, Py_ssize_t bytes)
21: {
22:     UINT8 n;
23:     UINT8* ptr;
24: 
25:     if (strcmp(im->mode, "1") == 0 && state->xsize > state->bytes * 8) {
26:         state->errcode = IMAGING_CODEC_OVERRUN;
27:         return -1;
28:     }
29: 
30:     ptr = buf;
31: 
32:     for (;;) {
33: 
34: 	if (bytes < 1)
35: 	    return ptr - buf;
36: 
37: 	if ((*ptr & 0xC0) == 0xC0) {
38: 
39: 	    /* Run */
40: 	    if (bytes < 2)
41: 		return ptr - buf;
42: 
43: 	    n = ptr[0] & 0x3F;
44: 
45: 	    while (n > 0) {
46: 		if (state->x >= state->bytes) {
47: 		    state->errcode = IMAGING_CODEC_OVERRUN;
48: 		    break;
49: 		}
50: 		state->buffer[state->x++] = ptr[1];
51: 		n--;
52: 	    }
53: 
54: 	    ptr += 2; bytes -= 2;
55: 
56: 	} else {
57: 
58: 	    /* Literal */
59: 	    state->buffer[state->x++] = ptr[0];
60: 	    ptr++; bytes--;
61: 
62: 	}
63: 
64: 	if (state->x >= state->bytes) {
65:         if (state->bytes % state->xsize && state->bytes > state->xsize) {
66:             int bands = state->bytes / state->xsize;
67:             int stride = state->bytes / bands;
68:             int i;
69:             for (i=1; i< bands; i++) {  // note -- skipping first band
70:                 memmove(&state->buffer[i*state->xsize],
71:                         &state->buffer[i*stride],
72:                         state->xsize);
73:             }
74:         }
75: 	    /* Got a full line, unpack it */
76: 	    state->shuffle((UINT8*) im->image[state->y + state->yoff] +
77: 			   state->xoff * im->pixelsize, state->buffer,
78: 			   state->xsize);
79: 
80: 	    state->x = 0;
81: 
82: 	    if (++state->y >= state->ysize) {
83: 		/* End of file (errcode = 0) */
84: 		return -1;
85: 	    }
86: 	}
87: 
88:     }
89: }

